              null, 'Doggerland, the lowland that once linked Britain to continental Europe, is the best-known example in the North Sea.', 'Paragraph A introduces Doggerland as a now-submerged lowland that once connected Britain with Europe.'
       from p
       on conflict (passage_id, idx) do update set
         kind = excluded.kind, prompt = excluded.prompt, options = excluded.options,
         evidence = excluded.evidence, explanation = excluded.explanation
       returning id
     )
